/// The Lens dropdown's labels, derived from [`LENS_LIBRARY`] so the two can
/// never drift out of alignment.
pub static LENS_OPTIONS: [&str; LENS_LIBRARY.len()] = {
    let mut out = [""; LENS_LIBRARY.len()];
    let mut i = 0;
    while i < out.len() {
        out[i] = LENS_LIBRARY[i].name;
        i += 1;
    }
    out
};
